      "Tarangire otwiera podróż prawdziwym półdniem samym w sobie, wraz z postojem w Mto wa Mbu i wizytą w społeczności Masajów wbudowaną w trasę, a nie oferowaną jako dodatek — to dom jednej z największych populacji słoni w Afryce Wschodniej, skoncentrowanej wzdłuż rzeki w porze suchej. Krater Ngorongoro otrzymuje pełny dzień, a nie pospieszny poranny postój: zapadnięta kaldera wulkaniczna o powierzchni około 260 km², ze ścianami na tyle stromymi, że większość tego, co w niej żyje, nigdy jej nie opuszcza, i jeden z najbardziej skoncentrowanych dni obserwacji dzikiej przyrody na całej trasie. Następnie dwa pełne dni na terytorium rezydentnych drapieżników Serengeti, zanim malowniczy lot — z przesiadką w Arushy — zamienia samochód na otwartą wodę i trzy niezaplanowane noce na białym piasku Nungwi.",
